CREATE OR REPLACE FUNCTION public.action_center_overtime_detail_v1(p_actor_email text, p_actor_session_id uuid, p_actor_session_version integer, p_release_sha text, p_tenant_id uuid, p_membership_id uuid, p_case_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  context_value jsonb;
  source_history jsonb;
  action_row action_case%ROWTYPE;
  contract_row employment_contract%ROWTYPE;
  batch_row source_import_batch%ROWTYPE;
  subject_name text;
  subject_sector text;
  reason_label text;
  decision_reason_label text;
  cancellation_reason_label text;
  timeline_value jsonb := '[]'::jsonb;
  commands_value jsonb := '[]'::jsonb;
  exclusive_entry boolean := false;
  separated_decider boolean := false;
BEGIN
  context_value := action_center_overtime_read_context_v1(
    p_actor_email, p_actor_session_id, p_actor_session_version,
    p_release_sha, p_tenant_id, p_membership_id
  );

  SELECT * INTO action_row
  FROM action_case action
  WHERE action.id = p_case_id
    AND action.case_type = 'overtime_entry'
    AND action.tenant_id = (context_value->>'tenantId')::uuid
    AND action.source_binding_id = (context_value->>'sourceBindingId')::uuid
    AND action.company_id = (context_value->>'sourceCompanyId')::bigint
  FOR SHARE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('principal', context_value, 'record', NULL);
  END IF;

  SELECT contract.* INTO contract_row
  FROM employment_contract contract
  WHERE contract.id = action_row.beneficiary_contract_id
    AND contract.source_system = 'GRH'
    AND contract.legacy_company_id = action_row.company_id
  FOR SHARE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('principal', context_value, 'record', NULL);
  END IF;

  SELECT * INTO batch_row
  FROM source_import_batch batch
  WHERE batch.id = action_row.source_batch_id
    AND batch.source_system = 'GRH'
    AND batch.source_database = context_value->>'sourceDatabase'
    AND batch.validation_state = 'published'
    AND batch.legacy_import_run_id IS NOT NULL
  FOR SHARE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('principal', context_value, 'record', NULL);
  END IF;

  PERFORM 1 FROM source_import_batch WHERE id = contract_row.source_batch_id FOR SHARE;
  source_history := action_center_case_source_context_v1(
    action_row.id, (context_value->>'tenantId')::uuid,
    (context_value->>'sourceBindingId')::uuid);
  IF source_history IS NULL THEN
    RETURN jsonb_build_object('principal', context_value, 'record', NULL);
  END IF;

  SELECT COALESCE(NULLIF(employee.nombre, ''), NULLIF(identity.full_name, ''), 'Nombre no informado'),
    COALESCE(NULLIF(employee.sector, ''), 'Sector no informado')
    INTO subject_name, subject_sector
  FROM person_identity identity
  LEFT JOIN grh_employees employee
    ON employee.company_id = contract_row.legacy_company_id
   AND employee.legajo = contract_row.legacy_legajo
   AND employee.import_run_id = batch_row.legacy_import_run_id
  WHERE identity.id = contract_row.person_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('principal', context_value, 'record', NULL);
  END IF;

  IF source_history #>> '{sourceContext,status}' = 'historical_read_only' THEN
    subject_name := source_history->>'displayName';
    subject_sector := source_history->>'displaySector';
  END IF;

  SELECT reason.label INTO reason_label
  FROM action_overtime_reason_catalog reason
  WHERE reason.policy_version_id = action_row.policy_version_id
    AND reason.reason_code = action_row.payload->>'reasonCode';
  SELECT reason.label INTO decision_reason_label
  FROM action_overtime_decision_reason_catalog reason
  WHERE reason.decision_reason_code = action_row.decision_reason;
  SELECT reason.label INTO cancellation_reason_label
  FROM action_overtime_decision_reason_catalog reason
  WHERE reason.decision_reason_code = action_row.cancellation_reason;

  exclusive_entry := action_center_overtime_has_exclusive_entry_v1(context_value);
  separated_decider := action_center_overtime_decider_separated_v1(
    action_row.id,
    (context_value->>'tenantId')::uuid,
    (context_value->>'sourceBindingId')::uuid,
    context_value->>'email',
    (context_value->>'actorPersonId')::uuid
  );
  IF action_row.status = 'draft' AND exclusive_entry THEN
    commands_value := jsonb_build_array('update_draft', 'submit', 'cancel');
  ELSIF action_row.status = 'submitted' THEN
    IF action_center_context_has_capability(context_value, 'time.overtime.approve')
       AND separated_decider THEN
      commands_value := commands_value || jsonb_build_array('approve', 'reject');
    END IF;
    IF exclusive_entry THEN
      commands_value := commands_value || jsonb_build_array('cancel');
    END IF;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
      'id', event.id,
      'caseVersion', event.case_version,
      'eventType', event.event_type,
      'fromStatus', event.from_status,
      'toStatus', event.to_status,
      'actorRole', event.actor_role,
      'metadata', jsonb_strip_nulls(jsonb_build_object(
        'command', event.metadata->>'command',
        'decisionReasonCode', event.metadata->>'decisionReasonCode',
        'reasonPresent', CASE WHEN event.metadata ? 'reasonPresent'
          THEN (event.metadata->>'reasonPresent')::boolean END,
        'evidenceStatus', event.metadata->>'evidenceStatus',
        'manualValidationConfirmed', CASE WHEN event.metadata ? 'manualValidationConfirmed'
          THEN (event.metadata->>'manualValidationConfirmed')::boolean END,
        'payrollCalculated', false,
        'payrollPosted', false
      )),
      'occurredAt', event.occurred_at
    )) ORDER BY event.id), '[]'::jsonb)
    INTO timeline_value
  FROM action_case_event event
  WHERE event.case_id = action_row.id
    AND event.case_type = 'overtime_entry'
    AND event.tenant_id = (context_value->>'tenantId')::uuid
    AND event.source_binding_id = (context_value->>'sourceBindingId')::uuid;

  RETURN jsonb_build_object(
    'principal', context_value,
    'record', jsonb_strip_nulls(jsonb_build_object(
      'id', action_row.id,
      'caseNumber', action_row.case_number,
    'sourceContext', source_history->'sourceContext',
      'caseType', action_row.case_type,
      'beneficiaryContractId', action_row.beneficiary_contract_id,
      'subject', jsonb_build_object(
        'contractId', action_row.beneficiary_contract_id,
        'displayName', subject_name,
        'legajo', contract_row.legacy_legajo,
        'sector', subject_sector
      ),
      'status', action_row.status,
      'confidentiality', action_row.confidentiality,
      'policyVersionId', action_row.policy_version_id,
      'payload', jsonb_build_object(
        'workDate', action_row.payload->>'workDate',
        'declaredMinutes', (action_row.payload->>'declaredMinutes')::integer,
        'reasonCode', action_row.payload->>'reasonCode',
        'reasonLabel', reason_label
      ),
      'evidenceStatus', action_row.evidence_status,
      'decision', CASE WHEN action_row.decision_reason IS NOT NULL THEN jsonb_build_object(
        'decisionReasonCode', action_row.decision_reason,
        'label', decision_reason_label,
        'manualValidationConfirmed', action_row.manual_validation_confirmed
      ) END,
      'cancellation', CASE WHEN action_row.cancellation_reason IS NOT NULL THEN jsonb_build_object(
        'decisionReasonCode', action_row.cancellation_reason,
        'label', cancellation_reason_label
      ) END,
      'timestamps', jsonb_strip_nulls(jsonb_build_object(
        'createdAt', action_row.created_at,
        'updatedAt', action_row.updated_at,
        'submittedAt', action_row.submitted_at,
        'decidedAt', action_row.decided_at,
        'cancelledAt', action_row.cancelled_at
      )),
      'version', action_row.version,
      'payrollImpact', jsonb_build_object(
        'amount', NULL,
        'rate', NULL,
        'calculated', false,
        'posted', false,
        'attendanceReconciled', false
      ),
      'projection', 'restricted_nominal'
    )),
    'timeline', timeline_value,
    'allowedCommands', CASE WHEN source_history #>> '{sourceContext,status}' = 'current'
      THEN commands_value ELSE '[]'::jsonb END
  );
END
$function$

CREATE OR REPLACE FUNCTION public.employee_family_declare_v1(p_email text, p_session uuid, p_version integer, p_release text, p_tenant uuid, p_membership uuid, p_payload jsonb, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE ctx jsonb; subject jsonb; previous employee_family_member%ROWTYPE; target uuid; new_id uuid:=gen_random_uuid();
 name_value text; dni_value text; birth_value date; from_value date; to_value date; request_hash text; snapshot jsonb; token text;
BEGIN
 ctx:=school_certificate_context_v1(p_email,p_session,p_version,p_release,p_tenant,p_membership,true,'family:'||p_key);
 -- Advisory serialization needs a fresh snapshot after a prior declaration commits.
 -- Reject fixed-snapshot callers rather than mutate the canonical employment row.
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'EMPLOYEE_FAMILY_ISOLATION_UNSUPPORTED'; END IF;
 IF p_key IS NULL OR p_key !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$' THEN RAISE EXCEPTION 'EMPLOYEE_FAMILY_IDEMPOTENCY_KEY_INVALID'; END IF;
 IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR NOT p_payload ?& ARRAY['contractId','contractIdentityToken','familyName','birthDate','dni','validFrom','validTo']
  OR p_payload-ARRAY['contractId','contractIdentityToken','familyName','birthDate','dni','validFrom','validTo']<>'{}'::jsonb
  OR EXISTS(SELECT 1 FROM jsonb_each(p_payload) e WHERE jsonb_typeof(e.value) NOT IN ('string','null'))
  OR coalesce(p_payload->>'contractId','') !~ '^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$'
  OR coalesce(p_payload->>'contractIdentityToken','') !~ '^[a-f0-9]{64}$'
  OR coalesce(length(p_payload->>'familyName'),0) NOT BETWEEN 1 AND 180
  OR p_payload->>'familyName' ~ '[[:cntrl:]<>]' THEN RAISE EXCEPTION 'EMPLOYEE_FAMILY_INVALID_PAYLOAD'; END IF;
 name_value:=normalize(regexp_replace(btrim(p_payload->>'familyName'),'[[:space:]]+',' ','g'),NFC);
 IF name_value IS DISTINCT FROM p_payload->>'familyName' OR name_value !~ '[^[:digit:][:space:][:punct:]]' COLLATE "C" THEN RAISE EXCEPTION 'EMPLOYEE_FAMILY_INVALID_PAYLOAD'; END IF;
 dni_value:=p_payload->>'dni';
 IF dni_value IS NOT NULL AND (dni_value !~ '^[0-9]{5,12}$' OR dni_value ~ '^0+$') THEN RAISE EXCEPTION 'EMPLOYEE_FAMILY_DOCUMENT_INVALID'; END IF;
 BEGIN
  IF EXISTS(SELECT 1 FROM jsonb_each_text(p_payload) e WHERE e.key IN ('birthDate','validFrom','validTo') AND e.value IS NOT NULL
   AND (e.value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR to_char(e.value::date,'YYYY-MM-DD')<>e.value OR e.value::date NOT BETWEEN DATE '1900-01-01' AND DATE '2100-12-31')) THEN RAISE EXCEPTION 'invalid'; END IF;
  birth_value:=(p_payload->>'birthDate')::date; from_value:=(p_payload->>'validFrom')::date; to_value:=(p_payload->>'validTo')::date;
  IF birth_value>(clock_timestamp() AT TIME ZONE 'America/Argentina/Buenos_Aires')::date OR to_value<from_value
   OR from_value<birth_value OR to_value<birth_value THEN RAISE EXCEPTION 'invalid'; END IF;
 EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'EMPLOYEE_FAMILY_DATES_INVALID'; END;
 target:=(p_payload->>'contractId')::uuid;
 -- Serializes all declarations for this subject, including different operators/keys.
 PERFORM pg_advisory_xact_lock(hashtextextended('employee-family:'||p_tenant::text||':'||(ctx->>'sourceBindingId')||':'||target::text,0));
 subject:=employee_family_subject_v1(ctx,target,true);
 IF subject->>'identityToken'<>p_payload->>'contractIdentityToken' THEN RAISE EXCEPTION 'EMPLOYEE_FAMILY_IDENTITY_CHANGED'; END IF;
 request_hash:=encode(digest(convert_to(p_payload::text,'UTF8'),'sha256'),'hex');
 SELECT * INTO previous FROM employee_family_member m WHERE m.tenant_id=p_tenant AND m.source_binding_id=(ctx->>'sourceBindingId')::uuid
  AND m.recorded_by_membership_id=p_membership AND m.idempotency_key=p_key;
 IF FOUND THEN
  IF previous.request_sha256<>request_hash THEN RAISE EXCEPTION 'EMPLOYEE_FAMILY_IDEMPOTENCY_REUSE'; END IF;
  IF previous.employee_person_id<>(subject->>'personId')::uuid OR previous.contract_identity_token<>subject->>'identityToken' THEN RAISE EXCEPTION 'EMPLOYEE_FAMILY_IDENTITY_CHANGED'; END IF;
  INSERT INTO employee_family_member_event(tenant_id,source_binding_id,actor_membership_id,actor_session_id,member_id,operation)
  VALUES(p_tenant,(ctx->>'sourceBindingId')::uuid,p_membership,p_session,previous.id,'replay');
  RETURN jsonb_build_object('version','employee-family-declare.v1','familyRef',jsonb_build_object('kind','own','id',previous.id),'identityToken',previous.identity_token,'state','declared','recordedAt',previous.recorded_at,'duplicate',true);
 END IF;
 -- Freeze the imported duplicate search, including inserts/refreshes, until commit.
 LOCK TABLE grh_family,grh_catalog_rows IN SHARE MODE NOWAIT;
 IF EXISTS(SELECT 1 FROM employee_family_member m WHERE m.tenant_id=p_tenant AND m.source_binding_id=(ctx->>'sourceBindingId')::uuid
   AND m.contract_id=target AND m.employee_person_id=(subject->>'personId')::uuid
   AND employee_family_identity_matches_v1(name_value,birth_value,dni_value,m.family_name,m.birth_date,m.dni))
  OR EXISTS(SELECT 1 FROM school_certificate_current_family_v1(ctx,target) f
   WHERE employee_family_identity_matches_v1(name_value,birth_value,dni_value,f.family_name,f.birth_date,normalize_digits(f.identity_snapshot->>'dni'))) THEN
  RAISE EXCEPTION 'EMPLOYEE_FAMILY_DUPLICATE';
 END IF;
 snapshot:=jsonb_build_object('kind','own','id',new_id,'tenantId',p_tenant,'sourceBindingId',ctx->>'sourceBindingId',
  'contractId',target,'personId',subject->>'personId','familyName',name_value,'birthDate',birth_value,'dni',dni_value,'validFrom',from_value,'validTo',to_value);
 token:=encode(digest(convert_to(snapshot::text,'UTF8'),'sha256'),'hex');
 INSERT INTO employee_family_member(id,tenant_id,source_binding_id,contract_id,employee_person_id,source_batch_id,contract_identity_token,
  family_name,name_key,birth_date,dni,valid_from,valid_to,identity_token,identity_snapshot,recorded_by_membership_id,recorded_by_session_id,idempotency_key,request_sha256)
 VALUES(new_id,p_tenant,(ctx->>'sourceBindingId')::uuid,target,(subject->>'personId')::uuid,(subject->>'sourceBatchId')::uuid,subject->>'identityToken',
  name_value,employee_family_name_key_v1(name_value),birth_value,dni_value,from_value,to_value,token,snapshot,p_membership,p_session,p_key,request_hash)
 RETURNING * INTO previous;
 INSERT INTO employee_family_member_event(tenant_id,source_binding_id,actor_membership_id,actor_session_id,member_id,operation)
 VALUES(p_tenant,(ctx->>'sourceBindingId')::uuid,p_membership,p_session,new_id,'declare');
 RETURN jsonb_build_object('version','employee-family-declare.v1','familyRef',jsonb_build_object('kind','own','id',new_id),'identityToken',token,'state','declared','recordedAt',previous.recorded_at,'duplicate',false);
EXCEPTION WHEN lock_not_available OR deadlock_detected THEN RAISE EXCEPTION 'EMPLOYEE_FAMILY_SESSION_BUSY';
 WHEN unique_violation THEN RAISE EXCEPTION 'EMPLOYEE_FAMILY_DUPLICATE';
 WHEN OTHERS THEN
  IF SQLERRM LIKE 'EMPLOYEE_FAMILY_%' OR SQLERRM LIKE 'SCHOOL_CERTIFICATE_%' THEN RAISE; END IF;
  RAISE EXCEPTION 'EMPLOYEE_FAMILY_UNAVAILABLE';
END $function$

CREATE OR REPLACE FUNCTION public.native_employee_create_v1(p jsonb, d jsonb, catalog_version text, k uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE ctx jsonb; catalogs jsonb; fingerprint text; r native_employee_registration%ROWTYPE; number_value text;
 person_value uuid:=gen_random_uuid(); contract_value uuid:=gen_random_uuid(); reg_value uuid:=gen_random_uuid();
 company_value bigint; today date:=(clock_timestamp() AT TIME ZONE 'America/Argentina/Mendoza')::date;
 birth_value date; start_value date; item jsonb; labels jsonb:='{}'; field_name text; kind text; code_value text;
BEGIN
 ctx:=native_employee_context_v1(p,true); company_value:=(ctx->>'sourceCompanyId')::bigint;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_ISOLATION_UNSUPPORTED'; END IF;
 IF k IS NULL OR k::text!~'^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
  OR catalog_version IS NULL OR catalog_version!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_INPUT_INVALID'; END IF;
 IF jsonb_typeof(d) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(d-'jurisdictionCode') key) IS DISTINCT FROM
  ARRAY['agreementCode','birthDate','categoryCode','cuil','dni','fullName','jobTitle','legajo','legalReference','organizationId','sectorCode','sexCode','startDate']::text[]
  THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_INPUT_INVALID'; END IF;
 IF d?'jurisdictionCode' AND (jsonb_typeof(d->'jurisdictionCode') IS DISTINCT FROM 'string' OR d->>'jurisdictionCode' NOT IN ('42','55'))
  THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_INPUT_INVALID'; END IF;
 FOR field_name IN SELECT jsonb_object_keys(d) LOOP
  IF jsonb_typeof(d->field_name) IS DISTINCT FROM 'string' OR d->>field_name<>btrim(d->>field_name) OR length(d->>field_name)>180 OR d->>field_name~'[<>[:cntrl:]]'
   THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_INPUT_INVALID'; END IF;
 END LOOP;
 IF length(d->>'fullName') NOT BETWEEN 3 AND 160 OR length(d->>'jobTitle')>120 OR length(d->>'legalReference') NOT BETWEEN 3 AND 180
  OR d->>'legajo'!~'^$|^[1-9][0-9]{0,8}$' OR d->>'dni'!~'^[0-9]{5,8}$' OR d->>'dni'~'^0+$'
  OR d->>'cuil'!~'^[0-9]{11}$' OR NOT is_valid_cuil(d->>'cuil') OR substring(d->>'cuil',3,8)<>lpad(d->>'dni',8,'0')
  OR d->>'sexCode' NOT IN('','F','M','X') THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_INPUT_INVALID'; END IF;
 BEGIN
  birth_value:=(d->>'birthDate')::date;start_value:=(d->>'startDate')::date;
  IF to_char(birth_value,'YYYY-MM-DD')<>d->>'birthDate' OR to_char(start_value,'YYYY-MM-DD')<>d->>'startDate'
   OR birth_value NOT BETWEEN DATE '1900-01-01' AND today OR start_value<birth_value OR start_value>DATE '2099-12-31'
   THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_INPUT_INVALID'; END IF;
 EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_INPUT_INVALID'; END;
 fingerprint:=encode(digest(convert_to(jsonb_build_object('draft',d,'catalogVersion',catalog_version)::text,'UTF8'),'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('native-employee-attempt:'||(ctx->>'tenantId')||':'||(ctx->>'membershipId')||':'||k::text,0));
 SELECT * INTO r FROM native_employee_registration WHERE tenant_id=(ctx->>'tenantId')::uuid AND actor_membership_id=(ctx->>'membershipId')::uuid AND request_key=k;
 IF FOUND THEN
  IF r.request_sha256<>fingerprint THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_ATTEMPT_CONFLICT'; END IF;
  RETURN native_employee_receipt_v1(r)||jsonb_build_object('replayed',true);
 END IF;
 catalogs:=native_employee_catalog_v1(ctx);
 IF catalogs->>'version'<>catalog_version THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_CATALOG_CHANGED'; END IF;
 FOREACH field_name IN ARRAY ARRAY['agreementCode','categoryCode','organizationId','sectorCode'] LOOP
  kind:=CASE field_name WHEN 'agreementCode' THEN 'agreements' WHEN 'categoryCode' THEN 'categories' WHEN 'organizationId' THEN 'organizations' ELSE 'sectors' END;
  SELECT value INTO item FROM jsonb_array_elements(catalogs->'items') WHERE value->>'kind'=kind AND value->>'code'=d->>field_name
   AND (kind<>'categories' OR value->>'agreementCode'=d->>'agreementCode');
  IF item IS NULL THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_CATALOG_SELECTION_INVALID'; END IF;
  labels:=labels||jsonb_build_object(field_name,item->>'label');
 END LOOP;
 -- Existing canonical CUIL uniqueness plus a DNI serialization lock; no fuzzy identity merges.
 PERFORM pg_advisory_xact_lock(hashtextextended('native-employee-dni:'||(d->>'dni'),0));
 IF EXISTS(SELECT 1 FROM person_identity WHERE identity_state IN('active','provisional') AND (cuil=d->>'cuil' OR dni=d->>'dni'))
  THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_IDENTITY_EXISTS'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('native-employee-company:'||company_value::text,0));
 number_value:=NULLIF(d->>'legajo','');
 IF number_value IS NULL THEN number_value:=native_employee_next_number_v1(company_value)::text; END IF;
 IF number_value!~'^[1-9][0-9]{0,8}$' THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_NUMBER_LIMIT'; END IF;
 IF EXISTS(SELECT 1 FROM employment_contract WHERE legacy_company_id=company_value AND ltrim(legacy_legajo,'0')=number_value)
  OR EXISTS(SELECT 1 FROM grh_employees WHERE company_id=company_value AND ltrim(legajo,'0')=number_value) THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_NUMBER_EXISTS'; END IF;
 INSERT INTO person_identity(id,cuil,dni,full_name,birth_date,sex_code,identity_state)
 VALUES(person_value,d->>'cuil',d->>'dni',d->>'fullName',birth_value,NULLIF(d->>'sexCode',''),'provisional');
 INSERT INTO native_employee_registration(id,tenant_id,source_binding_id,contract_id,person_id,actor_membership_id,actor_session_id,release_sha,request_key,request_sha256,catalog_sha256,legal_reference)
 VALUES(reg_value,(ctx->>'tenantId')::uuid,(ctx->>'sourceBindingId')::uuid,contract_value,person_value,(ctx->>'membershipId')::uuid,(p->>'actorSessionId')::uuid,p->>'releaseSha',k,fingerprint,catalog_version,d->>'legalReference') RETURNING * INTO r;
 INSERT INTO employment_contract(id,person_id,source_system,source_batch_id,tenant_id,legacy_company_id,legacy_legajo,start_date,
  agreement_code,category_code,organization_unit_source_id,sector_source_id,status,jurisdiction_code,source_payload)
 VALUES(contract_value,person_value,'MUNICONTROL',NULL,(ctx->>'tenantId')::uuid,company_value,number_value,start_value,
  d->>'agreementCode',d->>'categoryCode',d->>'organizationId',d->>'sectorCode','active',d->>'jurisdictionCode',
  jsonb_build_object('employment',jsonb_build_object('agreementName',labels->>'agreementCode','categoryName',labels->>'categoryCode',
  'organizationName',labels->>'organizationId','sectorName',labels->>'sectorCode','cargoName',NULLIF(d->>'jobTitle','')),
  'native',jsonb_build_object('registrationId',reg_value,'legalReference',d->>'legalReference','createdAt',r.created_at,'identityDeclared',true)));
 RETURN native_employee_receipt_v1(r)||jsonb_build_object('replayed',false);
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_DUPLICATE';
 WHEN lock_not_available OR deadlock_detected THEN RAISE EXCEPTION 'NATIVE_EMPLOYEE_BUSY';
END $function$

CREATE OR REPLACE FUNCTION public.school_certificate_family_v3(ctx jsonb, target uuid, kind text, family text, token text, hold_lock boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF kind IS NULL OR kind NOT IN ('grh','own') OR family IS NULL OR token IS NULL OR token !~ '^[a-f0-9]{64}$' OR target IS NULL
  OR (kind='grh' AND family !~ '^[0-9]{1,20}$')
  OR (kind='own' AND family !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$') THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_INVALID_PAYLOAD'; END IF;
 IF hold_lock THEN
  LOCK TABLE grh_family,grh_catalog_rows,employee_family_member IN SHARE MODE NOWAIT;
  PERFORM employee_family_subject_v1(ctx,target,true);
 END IF;
 SELECT to_jsonb(f) INTO result_value FROM school_certificate_current_family_v2(ctx,target) f WHERE f.family_kind=kind AND f.family_id=family;
 IF result_value IS NULL THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_NOT_FOUND'; END IF;
 IF result_value->>'identity_token'<>token THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_IDENTITY_CHANGED'; END IF;
 RETURN result_value;
EXCEPTION WHEN lock_not_available OR deadlock_detected THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SESSION_BUSY';
 WHEN OTHERS THEN
  IF SQLERRM LIKE 'SCHOOL_CERTIFICATE_%' THEN RAISE; END IF;
  IF SQLERRM='EMPLOYEE_FAMILY_NOT_FOUND' THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_NOT_FOUND'; END IF;
  RAISE EXCEPTION 'SCHOOL_CERTIFICATE_UNAVAILABLE';
END $function$

CREATE OR REPLACE FUNCTION public.school_certificate_read_v4(p_email text, p_session uuid, p_version integer, p_release text, p_tenant uuid, p_membership uuid, p_contract_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE ctx jsonb; base jsonb; items jsonb; source jsonb; item jsonb; effective jsonb; rec record;
BEGIN
 ctx:=school_certificate_context_v1(p_email,p_session,p_version,p_release,p_tenant,p_membership);
 -- v3 and the added source projection must describe the same source identity.
 -- Fail briefly when an import is in progress instead of combining two cuts.
 LOCK TABLE platform_tenant_source_binding,tenant_identity_policy,source_import_batch,employment_contract,person_identity,
  employment_status_snapshot,grh_family,grh_catalog_rows,employee_family_member,school_certificate_source_recovery,school_certificate_source_date IN SHARE MODE NOWAIT;
 base:=school_certificate_read_v3(p_email,p_session,p_version,p_release,p_tenant,p_membership,p_contract_id);
 items:='[]'::jsonb;
 FOR item IN SELECT value FROM jsonb_array_elements(base->'rows') LOOP
  source:=NULL;
  IF item#>>'{familyRef,kind}'='grh' THEN
   SELECT h.*,d.source_fields,b.source_cutoff,f.family_id INTO rec
   FROM school_certificate_source_recovery h JOIN school_certificate_source_date d ON d.recovery_id=h.id
   JOIN source_import_batch b ON b.id=h.source_batch_id AND b.validation_state='published' AND lower(b.source_sha256)=h.source_sha256 AND b.legacy_import_run_id=h.source_import_run_id
    AND b.source_cutoff=(h.source_declared_cutoff AT TIME ZONE 'America/Argentina/Buenos_Aires')
   JOIN employment_contract c ON c.id=(item->>'contractId')::uuid AND c.source_batch_id=b.id AND c.source_system='GRH'
   JOIN grh_family f ON f.family_id=d.family_id AND f.company_id=d.company_id AND f.legajo=d.legajo AND f.import_run_id=h.source_import_run_id
    AND f.company_id=c.legacy_company_id AND f.legajo=c.legacy_legajo AND f.vinculo_code='2' AND school_certificate_source_identity_v4(to_jsonb(f))=d.identity_sha256
   WHERE h.tenant_id=p_tenant AND h.source_binding_id=(ctx->>'sourceBindingId')::uuid AND d.family_id=(item#>>'{familyRef,id}')::bigint;
   IF FOUND THEN
    source:=jsonb_build_object('presentedOn',school_certificate_source_field_v4(rec.source_fields,'PRES_14')->'date','expiresOn',school_certificate_source_field_v4(rec.source_fields,'VENC_14')->'date',
     'presentationState',school_certificate_source_field_v4(rec.source_fields,'PRES_14')->>'state','expiryState',school_certificate_source_field_v4(rec.source_fields,'VENC_14')->>'state',
     'sourceSystem','GRH','sourceTable','familia','sourceKey',rec.family_id::text,'sourceSha256',rec.source_sha256,'sourceImportRunId',rec.source_import_run_id,
     'sourceBatchId',rec.source_batch_id,'sourceCutoff',rec.source_cutoff,'sourceDeclaredCutoff',to_char(rec.source_declared_cutoff,'YYYY-MM-DD"T"HH24:MI:SS'),
     'loadedAt',rec.loaded_at,'reviewState','historical_unreviewed','documentAvailable',false);
   END IF;
  END IF;
  effective:=CASE WHEN item->'certificate'<>'null'::jsonb THEN jsonb_build_object('origin','manual','presentedOn',item#>'{certificate,presentedOn}','expiresOn',item#>'{certificate,expiresOn}')
   WHEN source IS NOT NULL THEN jsonb_build_object('origin','grh_source','presentedOn',source->'presentedOn','expiresOn',source->'expiresOn')
   ELSE jsonb_build_object('origin','none','presentedOn',NULL,'expiresOn',NULL) END;
  items:=items||jsonb_build_array(item||jsonb_build_object('sourceSchooling',source,'effectiveDates',effective));
 END LOOP;
 RETURN base||jsonb_build_object('version','family-schooling.v4','rows',items);
EXCEPTION WHEN lock_not_available OR deadlock_detected OR serialization_failure THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SESSION_BUSY';
 WHEN OTHERS THEN IF SQLERRM LIKE 'SCHOOL_CERTIFICATE_%' THEN RAISE; END IF; RAISE EXCEPTION 'SCHOOL_CERTIFICATE_UNAVAILABLE'; END $function$

CREATE OR REPLACE FUNCTION public.school_certificate_register_v1(p_email text, p_session uuid, p_version integer, p_release text, p_tenant uuid, p_membership uuid, p_payload jsonb, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE ctx jsonb; current_family record; old_certificate school_certificate%ROWTYPE; new_id uuid;
 contract_value uuid; content_value bytea; presented_value date; expires_value date; request_hash text; item text;
BEGIN
 IF p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 1 AND 128
  OR p_idempotency_key !~ '^[A-Za-z0-9._:-]+$' THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_INVALID_PAYLOAD'; END IF;
 ctx:=school_certificate_context_v1(p_email,p_session,p_version,p_release,p_tenant,p_membership,true,p_idempotency_key);
 IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR NOT p_payload ?& ARRAY['contractId','familyId','identityToken','filename','contentBase64','sha256','presentedOn','expiresOn']
  OR p_payload-ARRAY['contractId','familyId','identityToken','filename','contentBase64','sha256','presentedOn','expiresOn']<>'{}'::jsonb THEN
  RAISE EXCEPTION 'SCHOOL_CERTIFICATE_INVALID_PAYLOAD';
 END IF;
 FOREACH item IN ARRAY ARRAY['contractId','familyId','identityToken','filename','contentBase64','sha256','presentedOn'] LOOP
  IF jsonb_typeof(p_payload->item) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_INVALID_PAYLOAD'; END IF;
 END LOOP;
 IF jsonb_typeof(p_payload->'expiresOn') NOT IN ('string','null') OR p_payload->>'contractId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  OR p_payload->>'familyId' !~ '^[0-9]{1,20}$' OR p_payload->>'identityToken' !~ '^[a-f0-9]{64}$'
  OR p_payload->>'sha256' !~ '^[a-f0-9]{64}$' OR length(p_payload->>'filename') NOT BETWEEN 5 AND 180
  OR p_payload->>'filename'<>btrim(p_payload->>'filename') OR lower(right(p_payload->>'filename',4))<>'.pdf'
  OR p_payload->>'filename' ~ '[[:cntrl:]/\\:*?"<>|]' THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_INVALID_PAYLOAD'; END IF;
 contract_value:=(p_payload->>'contractId')::uuid;
 IF length(p_payload->>'contentBase64')>2796204 THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_TOO_LARGE'; END IF;
 BEGIN
  content_value:=decode(p_payload->>'contentBase64','base64');
 EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_PDF_INVALID'; END;
 IF octet_length(content_value)>2097152 THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_TOO_LARGE'; END IF;
 IF octet_length(content_value)<10 OR substring(content_value FROM 1 FOR 5)<>decode('255044462d','hex')
  OR replace(encode(content_value,'base64'),E'\n','')<>p_payload->>'contentBase64'
  OR encode(digest(content_value,'sha256'),'hex')<>p_payload->>'sha256' THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_PDF_INVALID'; END IF;
 BEGIN
  IF p_payload->>'presentedOn' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
   OR (p_payload->>'expiresOn' IS NOT NULL AND p_payload->>'expiresOn' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$') THEN RAISE EXCEPTION 'invalid'; END IF;
  presented_value:=(p_payload->>'presentedOn')::date; expires_value:=(p_payload->>'expiresOn')::date;
  IF presented_value NOT BETWEEN DATE '1900-01-01' AND DATE '2100-12-31' OR to_char(presented_value,'YYYY-MM-DD')<>p_payload->>'presentedOn'
   OR (expires_value IS NOT NULL AND (expires_value NOT BETWEEN DATE '1900-01-01' AND DATE '2100-12-31' OR to_char(expires_value,'YYYY-MM-DD')<>p_payload->>'expiresOn')) THEN RAISE EXCEPTION 'invalid'; END IF;
 EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_DATES_INVALID'; END;
 request_hash:=encode(digest(convert_to(p_payload::text,'UTF8'),'sha256'),'hex');
 SELECT * INTO old_certificate FROM school_certificate d WHERE d.tenant_id=p_tenant
  AND d.source_binding_id=(ctx->>'sourceBindingId')::uuid AND d.recorded_by_membership_id=p_membership AND d.idempotency_key=p_idempotency_key;
 IF FOUND AND old_certificate.request_sha256<>request_hash THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_IDEMPOTENCY_REUSE'; END IF;
 -- Hold source identity until commit; a refresh/reassignment cannot race persistence.
 LOCK TABLE grh_family IN ACCESS SHARE MODE NOWAIT;
 LOCK TABLE grh_catalog_rows IN ACCESS SHARE MODE NOWAIT;
 -- Filter scope before taking any row lock, including rejected target IDs.
 PERFORM 1 FROM employment_contract c JOIN source_import_batch b ON b.id=c.source_batch_id
  WHERE c.id=contract_value AND c.source_system='GRH' AND c.legacy_company_id=(ctx->>'sourceCompanyId')::bigint
   AND b.source_system='GRH' AND b.source_database=ctx->>'sourceDatabase'
   AND b.validation_state='published' AND b.legacy_import_run_id IS NOT NULL FOR SHARE OF c NOWAIT;
 PERFORM 1 FROM source_import_batch b JOIN employment_contract c ON c.source_batch_id=b.id
  WHERE c.id=contract_value AND c.source_system='GRH' AND c.legacy_company_id=(ctx->>'sourceCompanyId')::bigint
   AND b.source_system='GRH' AND b.source_database=ctx->>'sourceDatabase'
   AND b.validation_state='published' AND b.legacy_import_run_id IS NOT NULL FOR SHARE OF b NOWAIT;
 PERFORM 1 FROM grh_catalog_rows k JOIN source_import_batch b ON b.legacy_import_run_id=k.import_run_id
  JOIN employment_contract c ON c.source_batch_id=b.id WHERE c.id=contract_value AND k.catalog='family_relationships'
  AND c.source_system='GRH' AND c.legacy_company_id=(ctx->>'sourceCompanyId')::bigint
  AND b.source_system='GRH' AND b.source_database=ctx->>'sourceDatabase' AND b.validation_state='published'
  AND k.source_payload #>> '{sourceKey,relationshipId}'='2' FOR SHARE OF k NOWAIT;
 PERFORM 1 FROM grh_family f JOIN employment_contract c ON c.legacy_company_id=f.company_id AND c.legacy_legajo=f.legajo
  JOIN source_import_batch b ON b.id=c.source_batch_id AND b.legacy_import_run_id=f.import_run_id
  WHERE c.id=contract_value AND c.source_system='GRH' AND c.legacy_company_id=(ctx->>'sourceCompanyId')::bigint
   AND b.source_system='GRH' AND b.source_database=ctx->>'sourceDatabase' AND b.validation_state='published'
   AND f.vinculo_code='2' AND f.family_id::text=p_payload->>'familyId' FOR SHARE OF f NOWAIT;
 SELECT * INTO current_family FROM school_certificate_current_family_v1(ctx,contract_value) f WHERE f.family_id=p_payload->>'familyId';
 IF NOT FOUND THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_NOT_FOUND'; END IF;
 IF current_family.identity_token<>p_payload->>'identityToken' THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_IDENTITY_CHANGED'; END IF;
 IF old_certificate.id IS NOT NULL THEN
  INSERT INTO school_certificate_event(tenant_id,source_binding_id,actor_membership_id,actor_session_id,certificate_id,operation,result_count)
  VALUES(p_tenant,(ctx->>'sourceBindingId')::uuid,p_membership,p_session,old_certificate.id,'replay',1);
  RETURN jsonb_build_object('version','family-schooling-register.v1','certificateId',old_certificate.id,'duplicate',true);
 END IF;
 PERFORM school_certificate_storage_reserve_v1(p_tenant,p_payload->>'sha256',octet_length(content_value));
 INSERT INTO school_certificate_blob(tenant_id,sha256,content,byte_length)
 VALUES(p_tenant,p_payload->>'sha256',content_value,octet_length(content_value)) ON CONFLICT DO NOTHING;
 INSERT INTO school_certificate(tenant_id,source_binding_id,contract_id,person_id,source_batch_id,source_database,company_id,source_legajo,
  family_id,identity_token,identity_snapshot,source_cutoff,filename,blob_sha256,presented_on,expires_on,
  recorded_by_membership_id,recorded_by_session_id,idempotency_key,request_sha256)
 VALUES(p_tenant,(ctx->>'sourceBindingId')::uuid,current_family.contract_id,current_family.person_id,current_family.source_batch_id,
  ctx->>'sourceDatabase',(ctx->>'sourceCompanyId')::bigint,current_family.legajo,current_family.family_id,current_family.identity_token,
  current_family.identity_snapshot,current_family.source_cutoff,p_payload->>'filename',p_payload->>'sha256',presented_value,expires_value,
  p_membership,p_session,p_idempotency_key,request_hash) RETURNING id INTO new_id;
 INSERT INTO school_certificate_event(tenant_id,source_binding_id,actor_membership_id,actor_session_id,certificate_id,operation,result_count)
 VALUES(p_tenant,(ctx->>'sourceBindingId')::uuid,p_membership,p_session,new_id,'register',1);
 RETURN jsonb_build_object('version','family-schooling-register.v1','certificateId',new_id,'duplicate',false);
EXCEPTION WHEN lock_not_available OR deadlock_detected THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SESSION_BUSY';
 WHEN OTHERS THEN
  IF SQLERRM LIKE 'SCHOOL_CERTIFICATE_%' THEN RAISE; END IF;
  RAISE EXCEPTION 'SCHOOL_CERTIFICATE_UNAVAILABLE';
END $function$

CREATE OR REPLACE FUNCTION public.school_certificate_source_import_v4(p_tenant uuid, p_binding uuid, p_batch uuid, p_payload jsonb, p_operator text, p_apply boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE b source_import_batch%ROWTYPE; r data_import_runs%ROWTYPE; binding platform_tenant_source_binding%ROWTYPE;
 prior school_certificate_source_recovery%ROWTYPE; n integer; expected integer; matched integer; rowset text; new_id uuid;
BEGIN
 IF current_user IS DISTINCT FROM (SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid='school_certificate_source_recovery'::regclass)
 THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SOURCE_OWNER_REQUIRED'; END IF;
 IF p_tenant IS NULL OR p_binding IS NULL OR p_batch IS NULL OR p_apply IS NULL OR p_operator IS NULL OR length(btrim(p_operator)) NOT BETWEEN 5 AND 160 OR p_operator<>btrim(p_operator) OR p_operator ~ '[[:cntrl:]]'
  OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' OR NOT p_payload ?& ARRAY['version','sourceSystem','sourceDatabase','sourceSha256','sourceDeclaredCutoff','rows']
  OR p_payload-ARRAY['version','sourceSystem','sourceDatabase','sourceSha256','sourceDeclaredCutoff','rows']<>'{}'::jsonb
  OR EXISTS(SELECT 1 FROM jsonb_each(CASE WHEN jsonb_typeof(p_payload)='object' THEN p_payload-'rows' ELSE '{}'::jsonb END) v WHERE jsonb_typeof(v.value)<>'string')
  OR p_payload->>'version'<>'schooling-source-recovery.v1' OR p_payload->>'sourceSystem'<>'GRH'
  OR p_payload->>'sourceSha256' !~ '^[a-f0-9]{64}$' OR p_payload->>'sourceDeclaredCutoff' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}$'
  OR jsonb_typeof(p_payload->'rows') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SOURCE_PAYLOAD_INVALID'; END IF;
 n:=jsonb_array_length(p_payload->'rows');
 IF n NOT BETWEEN 1 AND 5000 OR octet_length(p_payload::text)>2097152 THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SOURCE_PAYLOAD_INVALID'; END IF;
 IF p_apply THEN
  IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SOURCE_ISOLATION_REQUIRED'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('schooling-source-recovery:'||p_tenant||':'||p_binding||':'||p_batch,0));
  LOCK TABLE platform_tenant,platform_tenant_source_binding,tenant_identity_policy,source_import_batch,data_import_runs,grh_family,grh_catalog_rows IN SHARE MODE;
 END IF;
 SELECT sb.* INTO binding FROM platform_tenant_source_binding sb JOIN tenant_identity_policy ip ON ip.tenant_id=sb.tenant_id AND ip.certified_source_binding_id=sb.id
 JOIN platform_tenant t ON t.id=sb.tenant_id AND t.status='active'
 WHERE sb.id=p_binding AND sb.tenant_id=p_tenant AND sb.source_system='GRH' AND sb.verified AND ip.tenant_data_plane_ready;
 SELECT * INTO b FROM source_import_batch WHERE id=p_batch;
 SELECT * INTO r FROM data_import_runs WHERE id=b.legacy_import_run_id;
 IF binding.id IS NULL OR b.id IS NULL OR r.id IS NULL OR b.source_system IS DISTINCT FROM 'GRH' OR b.validation_state IS DISTINCT FROM 'published' OR r.status IS DISTINCT FROM 'completed'
  OR b.source_database IS DISTINCT FROM binding.source_database OR (p_payload->>'sourceDatabase') IS DISTINCT FROM b.source_database
  OR lower(b.source_sha256) IS DISTINCT FROM (p_payload->>'sourceSha256') OR lower(r.source_sha256) IS DISTINCT FROM (p_payload->>'sourceSha256')
  OR b.source_cutoff IS DISTINCT FROM (r.source_cutoff AT TIME ZONE 'America/Argentina/Buenos_Aires')
  OR to_char(r.source_cutoff,'YYYY-MM-DD"T"HH24:MI:SS') IS DISTINCT FROM (p_payload->>'sourceDeclaredCutoff')
 THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SOURCE_MISMATCH'; END IF;
 -- The original catalog authority distinguishes HIJO id2 from PRENATAL code H.
 IF NOT (SELECT count(*)=1 AND coalesce(bool_and(label='HIJO' AND source_payload->>'code'='H' AND source_payload->>'name'='HIJO'),false)
  FROM grh_catalog_rows WHERE catalog='family_relationships' AND import_run_id=r.id AND source_payload#>>'{sourceKey,relationshipId}'='2')
 THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SOURCE_MAPPING_DRIFT'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_payload->'rows') x WHERE jsonb_typeof(x) IS DISTINCT FROM 'object'
  OR NOT x ?& ARRAY['familyId','companyId','legajo','identitySha256','sourceFields'] OR x-ARRAY['familyId','companyId','legajo','identitySha256','sourceFields']<>'{}'::jsonb
  OR jsonb_typeof(x->'familyId') IS DISTINCT FROM 'string' OR x->>'familyId' !~ '^[1-9][0-9]{0,17}$'
  OR jsonb_typeof(x->'companyId') IS DISTINCT FROM 'number' OR x->>'companyId' !~ '^[1-9][0-9]{0,8}$'
  OR jsonb_typeof(x->'legajo') IS DISTINCT FROM 'string' OR length(x->>'legajo') NOT BETWEEN 1 AND 64
  OR jsonb_typeof(x->'identitySha256') IS DISTINCT FROM 'string' OR x->>'identitySha256' !~ '^[a-f0-9]{64}$'
  OR jsonb_typeof(x->'sourceFields') IS DISTINCT FROM 'object' OR (x->'sourceFields')-ARRAY['PRES_14','VENC_14']<>'{}'::jsonb
  OR EXISTS(SELECT 1 FROM jsonb_each(CASE WHEN jsonb_typeof(x->'sourceFields')='object' THEN x->'sourceFields' ELSE '{}'::jsonb END) v
   WHERE jsonb_typeof(v.value) NOT IN ('string','null') OR length(v.value#>>'{}')>80))
 THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SOURCE_PAYLOAD_INVALID'; END IF;
 IF (SELECT count(DISTINCT x->>'familyId') FROM jsonb_array_elements(p_payload->'rows') x)<>n THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SOURCE_PAYLOAD_INVALID'; END IF;
 SELECT count(*) INTO expected FROM grh_family f WHERE f.import_run_id=r.id AND f.company_id=binding.source_company_id AND f.vinculo_code='2';
 SELECT count(*) INTO matched FROM jsonb_array_elements(p_payload->'rows') x JOIN grh_family f
  ON f.family_id=(x->>'familyId')::bigint AND f.company_id=(x->>'companyId')::bigint AND f.legajo=x->>'legajo'
  AND f.import_run_id=r.id AND f.company_id=binding.source_company_id AND f.vinculo_code='2'
  AND school_certificate_source_identity_v4(to_jsonb(f))=x->>'identitySha256';
 IF expected<>n OR matched<>n THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SOURCE_IDENTITY_MISMATCH'; END IF;
 SELECT encode(digest(convert_to(jsonb_agg(x ORDER BY (x->>'familyId')::bigint)::text,'UTF8'),'sha256'),'hex') INTO rowset FROM jsonb_array_elements(p_payload->'rows') x;
 SELECT * INTO prior FROM school_certificate_source_recovery WHERE tenant_id=p_tenant AND source_binding_id=p_binding AND source_batch_id=p_batch;
 IF prior.id IS NOT NULL AND (prior.source_sha256<>p_payload->>'sourceSha256' OR prior.rowset_sha256<>rowset OR prior.row_count<>n
  OR (SELECT count(*) FROM school_certificate_source_date WHERE recovery_id=prior.id)<>n)
 THEN RAISE EXCEPTION 'SCHOOL_CERTIFICATE_SOURCE_CONFLICT'; END IF;
 IF p_apply AND prior.id IS NULL THEN
  INSERT INTO school_certificate_source_recovery(tenant_id,source_binding_id,source_batch_id,source_import_run_id,source_sha256,rowset_sha256,source_declared_cutoff,row_count,operator_label)
  VALUES(p_tenant,p_binding,p_batch,r.id,p_payload->>'sourceSha256',rowset,(p_payload->>'sourceDeclaredCutoff')::timestamp,n,p_operator) RETURNING id INTO new_id;
  INSERT INTO school_certificate_source_date(recovery_id,family_id,company_id,legajo,identity_sha256,source_fields)
  SELECT new_id,(x->>'familyId')::bigint,(x->>'companyId')::bigint,x->>'legajo',x->>'identitySha256',x->'sourceFields' FROM jsonb_array_elements(p_payload->'rows') x;
 END IF;
 RETURN jsonb_build_object('version','schooling-source-import.v1','applied',p_apply,'replayed',prior.id IS NOT NULL,'rows',n,'matched',matched,
  'sourceSha256',p_payload->>'sourceSha256','rowsetSha256',rowset,'originalRowsModified',0,'manualRecordsCreated',0,'payrollModified',false);
END $function$
